spec.query:
import "date"
import "math"

// Allow 30 seconds for recent readings to arrive.
// Only evaluate completed minutes.
cutoff = date.truncate(
    t: date.sub(d: 30s, from: now()),
    unit: 1m
)

start = date.sub(d: 1h, from: cutoff)

// Forecast timestamps already represent their target times.
predictions =
    from(bucket: "SmartPlantIoT")
        |> range(start: start, stop: cutoff)
        |> filter(fn: (r) =>
            r._measurement == "moisture_forecast" and
            r._field == "predicted_moisture" and
            r.device == "esp32-01"
        )
        |> keep(columns: [
            "_time", "_value", "device", "horizon", "model"
        ])
        |> rename(columns: {_value: "predicted"})
        |> group(columns: ["device"])

// Build actual minute averages.
// Require at least three readings in each minute.
actual =
    from(bucket: "SmartPlantIoT")
        |> range(start: start, stop: cutoff)
        |> filter(fn: (r) =>
            r._measurement == "moisture" and
            r._field == "moisture"
        )
        |> set(key: "device", value: "esp32-01")
        |> filter(fn: (r) => r._value >= 0 and r._value <= 100)
        |> keep(columns: ["_time", "_value", "device"])
        |> group(columns: ["device"])
        |> window(every: 1m)
        |> reduce(
            identity: {total: 0.0, readings: 0},
            fn: (r, accumulator) => ({
                total: accumulator.total + float(v: r._value),
                readings: accumulator.readings + 1
            })
        )
        |> filter(fn: (r) => r.readings >= 3)
        |> map(fn: (r) => ({
            _time: r._stop,
            device: r.device,
            actual: r.total / float(v: r.readings)
        }))
        |> group(columns: ["device"])

// predictions |> yield(name: "prediction_check")
// Match each forecast with actual moisture at its target time.
join(
    tables: {prediction: predictions, observation: actual},
    on: ["_time", "device"],
    method: "inner"
)
    // Calculate individual forecast errors.
    |> map(fn: (r) => ({
        device: r.device,
        model: r.model,
        horizon: r.horizon,
        error: r.predicted - r.actual
    }))

    // Evaluate each model and horizon separately.
    |> group(columns: ["device", "model", "horizon"])

    // Accumulate the number of pairs and their errors.
    |> reduce(
        identity: {
            samples: 0,
            absolute_sum: 0.0,
            squared_sum: 0.0
        },
        fn: (r, accumulator) => ({
            samples: accumulator.samples + 1,
            absolute_sum:
                accumulator.absolute_sum + math.abs(x: r.error),
            squared_sum:
                accumulator.squared_sum + r.error * r.error
        })
    )

    // MAE = sum of absolute errors / number of pairs.
    // RMSE = sqrt(sum of squared errors / number of pairs).
    |> map(fn: (r) => ({
        device: r.device,
        model: r.model,
        horizon: r.horizon,
        samples: r.samples,
        MAE: r.absolute_sum / float(v: r.samples),
        RMSE: math.sqrt(
            x: r.squared_sum / float(v: r.samples)
        )
    }))
    |> group()
    |> sort(columns: ["model", "horizon"])
    |> yield(name: "live_metrics")
